代码片段（语言: javascript）：
```javascript
// featureFlagService.js —— 功能开关管理（变体1）
const express = require('express');
const app = express();
app.use(express.json());

// 全局功能开关表
const featureFlags = { betaSearch: false, darkMode: false };

// 递归深合并：键名未做任何过滤，直接写入目标对象
function deepMerge(target, source) {
  for (const key in source) {
    if (typeof source[key] === 'object' && source[key] !== null) {
      if (!target[key]) target[key] = {};
      deepMerge(target[key], source[key]);        // 递归赋值
    } else {
      target[key] = source[key];                  // 深赋值写入
    }
  }
  return target;
}

// POST /flags/update —— 更新功能开关
// 载荷：{"__proto__": {"isAdmin": true}}
app.post('/flags/update', (req, res) => {
  deepMerge(featureFlags, req.body);              // 外部载荷直达递归合并
  // 污染后 Object.prototype.isAdmin === true，
  // 任意新建对象沿原型链继承 isAdmin，权限校验被绕过
  const user = { name: 'guest' };
  if (user.isAdmin) grantAdminPanel(user);        // 污染链终点：权限标志
  res.json({ ok: true });
});

function grantAdminPanel(u) { console.log('admin panel granted:', u.name); }
app.listen(3000);
```

