      if (!target[key]) target[key] = {};
      deepMerge(target[key], source[key]);   // 递归写入 target[key]
    } else {
      target[key] = source[key];             // 深赋值
    }
  }
  return target;
}
// 载荷：POST /i18n/merge，body 为 {"lang":"zh-CN","overrides":{"__proto__":{"isAdmin":true}}}
app.post('/i18n/merge', (req, res) => {
  const { lang, overrides } = req.body;      // 外部 JSON 载荷，客户端完全可控
  const dict = i18nMessages[lang] || {};
  deepMerge(dict, overrides);                // 攻击者键名 __proto__ 进入递归合并
  res.json({ ok: true, greeting: dict.greeting });
});
// 权限校验点：依赖 isAdmin 标志
