// 权限矩阵合并服务：租户提交的角色权限矩阵被合并进全局角色表
const express = require('express');
const app = express();
app.use(express.json());

// 全局权限矩阵，viewer 角色默认只读
const roleMatrix = { viewer: { canRead: true, canWrite: false } };

// 递归合并权限矩阵：for-in 键遍历 + 递归深赋值，无任何键名过滤
function mergeMatrix(target, source) {
  for (const key in source) {
