  mergeMatrix(roleMatrix, req.body);
  // 污染后 Object.prototype.isAdmin === true，任意对象读取 isAdmin 均继承 true
  res.json({ viewer: roleMatrix.viewer, isAdmin: roleMatrix.viewer.isAdmin });
});

app.listen(3000, () => console.log('listening on 3000'));
```

