// 缓存选项合并服务（变体1）：外部 JSON 载荷经递归 merge 写入共享缓存配置
const express = require('express');
const app = express();
app.use(express.json());

// 模块级共享的默认缓存选项
const defaultCacheOptions = { ttl: 300, maxKeys: 1000, policy: 'lru' };

// 递归合并：for-in 键遍历 + target[key] = source[key]，无任何键名过滤
function mergeCacheOptions(target, source) {
  for (const key in source) {
    if (typeof source[key] === 'object' && source[key] !== null) {
      if (!target[key]) target[key] = {};
      mergeCacheOptions(target[key], source[key]); // 递归深赋值
    } else {
      target[key] = source[key]; // 直接写入，未过滤 __proto__ 等原型键
    }
  }
  return target;
}

// POST /cache/config  攻击载荷：{"__proto__": {"isAdmin": true}}
app.post('/cache/config', (req, res) => {
  const userOptions = req.body; // 外部输入入口：键名完全由攻击者控制
  mergeCacheOptions(defaultCacheOptions, userOptions);
  // 污染发生后 Object.prototype.isAdmin === true
  if (defaultCacheOptions.isAdmin) {
    grantAdminCacheScope(req.ip); // 权限标志沿原型链被命中
  }
  res.json({ applied: defaultCacheOptions });
});

function grantAdminCacheScope(ip) {
  console.log('admin cache scope granted:', ip);
}

app.listen(3000);
```

